			t.Errorf("sub-agent at 5%% = %v, want neutral", got)
		}
	})
	t.Run("60 and 40", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{withModel(orchestrator(0, 0), 600), withModel(subAgent("a01", "coder", 0, 0), 400)}}
		rows := agentRows(u, true, statusClock{}, prices)
		for i := range rows {
			if got := fg(rows, i); got != none {
				t.Errorf("row %d at 60/40 = %v, want neutral", i, got)
			}
		}
	})
	t.Run("a single priced agent colours nothing", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{withModel(orchestrator(0, 0), 1000), subAgent("a01", "coder", 0, 0)}}
		rows := agentRows(u, true, statusClock{}, prices)
		for i := range rows {
			if got := fg(rows, i); got != none && got != theme.DimStyle.GetForeground() {
				t.Errorf("row %d: %v, want neutral or dim", i, got)
			}
		}
	})
	t.Run("no price table colours nothing", func(t *testing.T) {
		u := agentusage.Usage{Agents: []agentusage.Agent{withModel(orchestrator(0, 0), 950), withModel(subAgent("a01", "coder", 0, 0), 50)}}
		for i, r := range agentRows(u, true, statusClock{}, pricing.Table{}) {
			if got := col.Style(r).GetForeground(); got != theme.DimStyle.GetForeground() {
				t.Errorf("row %d unpriced = %v, want dim", i, got)
			}
		}
	})
}

func TestTheHelpSaysWhatTheCostColoursMean(t *testing.T) {
	var body string
	for _, s := range runningTeam(t).GetHelpContent().Sections {
		if s.Title == "Costs" {
			body = s.Body
		}
	}
	if body == "" {
		t.Fatal("no Costs section in the help")
	}
	for _, want := range []string{"75", "90"} {
		if !contains(body, want) {
			t.Errorf("Costs help does not mention %s%% as a colour threshold:\n%s", want, body)
		}
	}
}

func contains(s, sub string) bool { return len(sub) > 0 && indexOf(s, sub) >= 0 }

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
